package com.clinictraining.medbackend.api;

import com.clinictraining.appointment.model.Appointment;
import com.clinictraining.appointment.model.AppointmentStatus;
import com.clinictraining.appointment.model.AppointmentType;
import com.clinictraining.medbackend.api.dto.AppointmentResponse;
import com.clinictraining.patient.mapper.PatientMapper;
import com.clinictraining.patient.mapper.ProviderMapper;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

class ApiMapperTest {

    private ApiMapper apiMapper;

    @BeforeEach
    void setUp() {
        apiMapper = new ApiMapper(Mockito.mock(PatientMapper.class), Mockito.mock(ProviderMapper.class));
    }

    @Test
    void shouldMapAppointmentTypeCode() {
        AppointmentType type = new AppointmentType();
        type.setTypeCode("TEL_VISIT");
        type.setDescription("Telehealth visit");
        Appointment appointment = appointment();
        appointment.setAppointmentType(type);

        AppointmentResponse response = apiMapper.toResponse(appointment);

        Assertions.assertEquals("TEL_VISIT", response.getAppointmentTypeCode());
    }

    @Test
    void shouldMapNullAppointmentTypeCodeWhenTypeMissing() {
        Appointment appointment = appointment();
        appointment.setAppointmentType(null);

        AppointmentResponse response = apiMapper.toResponse(appointment);

        Assertions.assertNull(response.getAppointmentTypeCode());
    }

    private Appointment appointment() {
        Appointment appointment = new Appointment();
        appointment.setId(1L);
        appointment.setAppointmentCode("APT-1");
        appointment.setStatus(AppointmentStatus.SCHEDULED);
        return appointment;
    }
}

